import hashlib, http.server, io, json, os, shutil, sys, tarfile, tempfile, threading, time, unittest
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
import protonupd as P

VDF = '''"InstallConfigStore"
{
\t"Software"
\t{
\t\t"Valve"
\t\t{
\t\t\t"Steam"
\t\t\t{
\t\t\t\t"CompatToolMapping"
\t\t\t\t{
\t\t\t\t\t"438100"
\t\t\t\t\t{
\t\t\t\t\t\t"name"\t\t"GE-Proton11-11-x86_64"
\t\t\t\t\t\t"config"\t\t""
\t\t\t\t\t\t"priority"\t\t"250"
\t\t\t\t\t}
\t\t\t\t}
\t\t\t}
\t\t}
\t}
}
'''


def make_tar(path, top, tool, extra=None):
    with tarfile.open(path, "w:gz") as t:
        data = f'"compatibilitytools"\n{{\n  "compat_tools"\n  {{\n    "{tool}"\n    {{\n    }}\n  }}\n}}\n'.encode()
        for name, content in (("compatibilitytool.vdf", data), ("proton", b"#!/bin/sh\n")) if extra is None else extra:
            ti = tarfile.TarInfo(f"{top}/{name}"); ti.size = len(content); t.addfile(ti, io.BytesIO(content))


class Base(unittest.TestCase):
    def setUp(self):
        self.tmp = Path(tempfile.mkdtemp())
        self.srv_dir = self.tmp / "srv"; self.srv_dir.mkdir()
        h = lambda *a, **k: http.server.SimpleHTTPRequestHandler(*a, directory=str(self.srv_dir), **k)
        h.log_message = lambda *a: None
        self.httpd = http.server.ThreadingHTTPServer(("127.0.0.1", 0), h)
        threading.Thread(target=self.httpd.serve_forever, daemon=True).start()
        self.base = f"http://127.0.0.1:{self.httpd.server_port}"
        P.STEAM = self.tmp / "Steam"; P.COMPAT = P.STEAM / "compatibilitytools.d"; P.CFG_VDF = P.STEAM / "config/config.vdf"
        (P.STEAM / "config").mkdir(parents=True); P.COMPAT.mkdir()
        P.CFG_VDF.write_text(VDF)
        P.CONF = self.tmp / "conf/config.json"; P.NAMES = P.CONF.parent / "installed.json"; P.CACHE = self.tmp / "cache"
        for k in [k for k in P.SOURCES if P.SOURCES[k].get("custom")]:
            del P.SOURCES[k]
        self.steam = False; self.notes = []
        P.steam_running = lambda: self.steam
        P.notify = lambda m: self.notes.append(m)
        self.releases_data = []
        P.http_json = lambda url: self.releases_data
        # an "already installed" 11-11
        (P.COMPAT / "GE-Proton11-11-x86_64").mkdir()

    def tearDown(self):
        self.httpd.shutdown(); shutil.rmtree(self.tmp, ignore_errors=True)

    def publish_ge(self, n, bad_sha=False):
        tag = f"GE-Proton11-{n}"; fn = f"{tag}-x86_64.tar.gz"
        make_tar(self.srv_dir / fn, tag, f"{tag}-x86_64")
        sha = hashlib.sha512((self.srv_dir / fn).read_bytes()).hexdigest()
        (self.srv_dir / f"{tag}-x86_64.sha512sum").write_text(("0" * 128 if bad_sha else sha) + "  " + fn + "\n")
        self.releases_data.insert(0, {"tag_name": tag, "html_url": "u", "published_at": "2026-10-20T00:00:00Z",
            "assets": [{"name": fn, "browser_download_url": f"{self.base}/{fn}", "size": 100},
                       {"name": f"{tag}-x86_64.sha512sum", "browser_download_url": f"{self.base}/{tag}-x86_64.sha512sum", "size": 1}]})

    def cfg(self, **games):
        c = P.load(); c["games"] = games or {"438100": {"name": "VRChat", "source": "ge", "pin": None}}
        return c


class Flow(Base):
    def test_new_release_installs_and_switches(self):
        self.publish_ge(11); self.publish_ge(12)
        c = self.cfg(); P.check(c, lambda *_: None)
        self.assertTrue((P.COMPAT / "GE-Proton11-12-x86_64/compatibilitytool.vdf").exists())
        self.assertEqual(c["pending"], {"438100": "GE-Proton11-12-x86_64"})
        P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-12-x86_64")
        self.assertEqual(c["pending"], {})

    def test_steam_running_keeps_pending_and_notifies(self):
        self.publish_ge(12); self.steam = True
        c = self.cfg(); P.check(c, lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-11-x86_64")      # untouched
        self.assertIn("438100", c["pending"]); self.assertTrue(self.notes)
        self.steam = False; P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-12-x86_64")

    def test_bad_checksum_installs_nothing(self):
        self.publish_ge(12, bad_sha=True)
        with self.assertRaises(RuntimeError):
            P.check(self.cfg(), lambda *_: None)
        self.assertFalse((P.COMPAT / "GE-Proton11-12-x86_64").exists())
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-11-x86_64")

    def test_pinned_game_is_not_moved(self):
        self.publish_ge(12); self.publish_ge(11)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": "GE-Proton11-11"}})
        P.check(c, lambda *_: None)
        self.assertEqual(c["pending"], {})

    def test_pin_older_version_downloads_and_switches(self):
        self.publish_ge(9); self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": "GE-Proton11-9"}})
        P.check(c, lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-9-x86_64")

    def test_new_game_entry_is_created_in_mapping(self):
        self.publish_ge(12)
        c = self.cfg(**{"999": {"name": "X", "source": "ge", "pin": None}})
        P.check(c, lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("999"), "GE-Proton11-12-x86_64")
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-11-x86_64")
        t = P.CFG_VDF.read_text(); self.assertEqual(t.count("{"), t.count("}"))

    def test_missing_mapping_section_is_created(self):
        P.CFG_VDF.write_text('"InstallConfigStore"\n{\n\t"Software"\n\t{\n\t\t"Valve"\n\t\t{\n\t\t\t"Steam"\n\t\t\t{\n'
                             '\t\t\t\t"AutoUpdateWindowEnabled"\t\t"0"\n\t\t\t}\n\t\t}\n\t}\n}\n')
        self.publish_ge(12); c = self.cfg(); P.check(c, lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-12-x86_64")
        t = P.CFG_VDF.read_text(); self.assertEqual(t.count("{"), t.count("}"))

    def test_backup_of_config_is_made(self):
        self.publish_ge(12); c = self.cfg(); P.check(c, lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertTrue(Path(str(P.CFG_VDF) + ".bak-protonupd").exists())

    def test_cleanup_keeps_used_and_newest(self):
        for n in (8, 9, 10, 12):
            (P.COMPAT / f"GE-Proton11-{n}-x86_64").mkdir()
        c = self.cfg(); P.cleanup(c, lambda *_: None)
        left = sorted(d.name for d in P.COMPAT.iterdir())
        self.assertIn("GE-Proton11-11-x86_64", left)            # in use
        self.assertIn("GE-Proton11-12-x86_64", left)            # newest
        self.assertNotIn("GE-Proton11-8-x86_64", left)

    def test_restart_refuses_while_game_runs(self):
        P.game_running = lambda: True
        with self.assertRaises(RuntimeError):
            P.restart_steam(self.cfg(), lambda *_: None)


class AutoSwitch(Base):
    def test_auto_off_game_is_not_touched_but_bell_notified_once(self):
        self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": None, "auto": False}})
        P.check(c, lambda *_: None); P.check(c, lambda *_: None)
        self.assertFalse((P.COMPAT / "GE-Proton11-12-x86_64").exists())            # nothing downloaded
        self.assertEqual(c["pending"], {}); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-11-x86_64")
        self.assertEqual(sum("VRChat" in n for n in self.notes), 1)

    def test_auto_on_game_updates_by_itself(self):
        self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": None, "auto": True}})
        P.check(c, lambda *_: None, background=True); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-12-x86_64")

    def test_global_off_blocks_background_but_not_manual(self):
        self.publish_ge(12)
        c = self.cfg(); c["auto_global"] = False
        P.check(c, lambda *_: None, background=True)
        self.assertFalse((P.COMPAT / "GE-Proton11-12-x86_64").exists()); self.assertEqual(c["pending"], {})
        self.assertTrue(self.notes)                                                   # you are only told
        P.check(c, lambda *_: None)                                                   # button pressed by hand
        self.assertEqual(c["pending"], {"438100": "GE-Proton11-12-x86_64"})

    def test_update_now_works_even_when_auto_is_off(self):
        self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": None, "auto": False}})
        P.update_game(c, "438100", lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("438100"), "GE-Proton11-12-x86_64")
        self.assertFalse(c["games"]["438100"]["auto"])                               # the switch stays off

    def test_turning_auto_back_on_catches_up(self):
        self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": None, "auto": False}})
        P.check(c, lambda *_: None); self.assertEqual(c["pending"], {})
        c["games"]["438100"]["auto"] = True
        P.check(c, lambda *_: None); self.assertEqual(c["pending"], {"438100": "GE-Proton11-12-x86_64"})

    def test_cli_switches_persist(self):
        P.main(["auto", "off"]); self.assertFalse(P.load()["auto_global"])
        P.main(["auto", "on"]); self.assertTrue(P.load()["auto_global"])
        c = P.load(); c["games"]["438100"] = {"name": "V", "source": "ge", "pin": None}; P.save(c)
        P.main(["auto", "off", "438100"]); self.assertFalse(P.load()["games"]["438100"]["auto"])


class LogLines(Base):
    def test_check_explains_what_it_found(self):
        import i18n; i18n.set_lang("en")
        self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": None},
                        "2": {"name": "Pinned", "source": "ge", "pin": "GE-Proton11-12"},
                        "3": {"name": "Off", "source": "ge", "pin": None, "auto": False}})
        i18n.set_lang("en"); lines = []; P.check(c, lines.append)          # cfg() resets the language to the system one
        text = "\n".join(lines)
        self.assertIn("VRChat: new version GE-Proton11-12-x86_64 is ready", text)
        self.assertIn("Off: newer version", text)                 # auto-update off, newer exists
        self.assertIn("auto-update is off", text)

    def test_check_logs_up_to_date_games_by_name(self):
        import i18n; i18n.set_lang("en")
        self.publish_ge(11)
        c = self.cfg(); i18n.set_lang("en"); lines = []; P.check(c, lines.append)
        self.assertTrue(any("VRChat: GE-Proton11-11-x86_64 — up to date" in l for l in lines), lines)

    def test_check_app_reports_both_cases(self):
        import i18n; i18n.set_lang("en")
        self.releases_data = {"tag_name": "v99.0.0", "html_url": "p"}; out = []
        P.check_app(out.append); self.assertIn("99.0.0", out[0])
        self.releases_data = {"tag_name": "v" + P.VERSION, "html_url": "p"}; out = []
        P.check_app(out.append); self.assertIn("the latest version", out[0])


class Custom(Base):
    def test_custom_source_end_to_end(self):
        fn = "proton-em-10.0-34.tar.xz"
        with tarfile.open(self.srv_dir / fn, "w:xz") as t:
            data = b'"compatibilitytools"\n{\n  "compat_tools"\n  {\n    "proton-em-10.0-34"\n    {\n    }\n  }\n}\n'
            ti = tarfile.TarInfo("proton-em-10.0-34-folder/compatibilitytool.vdf"); ti.size = len(data); t.addfile(ti, io.BytesIO(data))
        sha = hashlib.sha512((self.srv_dir / fn).read_bytes()).hexdigest()
        (self.srv_dir / "proton-em-10.0-34.sha512sum").write_text(sha + "  " + fn)
        self.releases_data = [{"tag_name": "em-34", "html_url": "u", "published_at": "2026-10-01T00:00:00Z", "assets": [
            {"name": fn, "browser_download_url": f"{self.base}/{fn}", "size": 10},
            {"name": "proton-em-10.0-34.sha512sum", "browser_download_url": f"{self.base}/proton-em-10.0-34.sha512sum", "size": 1}]}]
        c = P.load(); key = P.add_custom(c, "https://github.com/someone/Proton-EM/", "EM")
        self.assertIn(key, P.load()["custom"])                    # persisted and reloaded
        c = P.load(); c["games"] = {"555": {"name": "G", "source": key, "pin": None}}
        P.check(c, lambda *_: None); P.apply_pending(c, lambda *_: None)
        self.assertEqual(P.current_tool("555"), "proton-em-10.0-34")             # internal name, not the folder name
        self.assertTrue((P.COMPAT / "proton-em-10.0-34-folder").exists())
        P.check(c, lambda *_: None)                                               # second run must not re-download
        self.assertEqual(c["pending"], {})

    def test_custom_rejects_bad_input(self):
        c = P.load()
        with self.assertRaises(RuntimeError): P.add_custom(c, "not a repo")
        self.releases_data = []
        with self.assertRaises(RuntimeError): P.add_custom(c, "a/b")
        self.assertEqual(P.load()["custom"], {})

    def test_remove_custom_drops_its_games(self):
        self.releases_data = [{"tag_name": "t", "html_url": "u", "published_at": "2026-10-01T00:00:00Z",
                               "assets": [{"name": "p-x86_64.tar.gz", "browser_download_url": "x", "size": 1}]}]
        c = P.load(); key = P.add_custom(c, "a/b"); c["games"]["7"] = {"name": "G", "source": key, "pin": None}
        P.remove_custom(c, key)
        self.assertNotIn("7", c["games"]); self.assertNotIn(key, P.SOURCES)


class BellAndSelfUpdate(Base):
    def rel(self, tag, name=None):
        return {"tag": tag, "name": name or tag + "-x86_64", "url": "u/" + tag}

    def test_needs_update_unpinned(self):
        g = {"source": "ge", "pin": None}
        self.assertFalse(P.needs_update("438100", g, self.rel("GE-Proton11-11")))     # same as installed
        self.assertTrue(P.needs_update("438100", g, self.rel("GE-Proton11-12")))
        self.assertFalse(P.needs_update("438100", g, None))                            # nothing known yet

    def test_needs_update_pinned(self):
        g = {"source": "ge", "pin": "GE-Proton11-9"}
        self.assertTrue(P.needs_update("438100", g, self.rel("GE-Proton11-12")))      # bell: newer than the pin
        self.assertFalse(P.needs_update("438100", g, self.rel("GE-Proton11-9")))

    def test_pinned_bell_notification_only_once(self):
        self.publish_ge(12)
        c = self.cfg(**{"438100": {"name": "VRChat", "source": "ge", "pin": "GE-Proton11-11"}})
        P.check(c, lambda *_: None); P.check(c, lambda *_: None)
        self.assertEqual(sum("VRChat" in n for n in self.notes), 1)

    def test_version_compare(self):
        self.assertTrue(P.newer_version("v1.10.0", "1.9.3"))
        self.assertFalse(P.newer_version("v1.2.0", "1.2.0"))
        self.assertFalse(P.newer_version("1.1.9", "1.2.0"))

    def test_app_update_detection_and_single_notification(self):
        self.releases_data = {"tag_name": "v99.0.0", "html_url": "page", "body": "notes"}
        u = P.app_update(); self.assertEqual(u["version"], "99.0.0")
        self.releases_data = {"tag_name": "v" + P.VERSION, "html_url": "page"}
        self.assertIsNone(P.app_update())
        self.releases_data = {"tag_name": "v99.0.0", "html_url": "page"}
        P.CONF.parent.mkdir(parents=True, exist_ok=True)
        c = P.load(); c["last_check"] = time.time(); P.save(c)       # skip the Proton check in run()
        P.run(); P.run()
        self.assertEqual(sum("99.0.0" in n for n in self.notes), 1)


class Cache(unittest.TestCase):
    def test_stale_cache_used_when_offline(self):
        tmp = Path(tempfile.mkdtemp()); P.CACHE = tmp
        url = "http://127.0.0.1:9/never"
        f = tmp / (hashlib.sha1(url.encode()).hexdigest() + ".json")
        f.write_text(json.dumps({"t": time.time() - 99999, "etag": "x", "body": [1]}))
        import importlib; importlib.reload(P); P.CACHE = tmp
        self.assertEqual(P.http_json(url), [1])
        shutil.rmtree(tmp)


